import{_ as a}from"./chunks/ark_rtk_gps_l1_l5.DKxil4tc.js";import{_ as r,a as t,b as i}from"./chunks/ark_rtk_gps_ublox_f9p_firmware_update.1pVrltzr.js";import{_ as o,o as l,c as n,al as s}from"./chunks/framework.7vp1BMOE.js";const S=JSON.parse('{"title":"ARK RTK GPS L1 L5","description":"","frontmatter":{},"headers":[],"relativePath":"uk/dronecan/ark_rtk_gps_l1_l2.md","filePath":"uk/dronecan/ark_rtk_gps_l1_l2.md"}'),d={name:"uk/dronecan/ark_rtk_gps_l1_l2.md"};function c(h,e,u,f,_,p){return l(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="ark-rtk-gps-l1-l5" tabindex="-1">ARK RTK GPS L1 L5 <a class="header-anchor" href="#ark-rtk-gps-l1-l5" aria-label="Permalink to &quot;ARK RTK GPS L1 L5&quot;">​</a></h1><p><a href="https://arkelectron.gitbook.io/ark-documentation/sensors/ark-rtk-gps" target="_blank" rel="noreferrer">ARK RTK GPS L1 L5</a> is an open source <a href="./">DroneCAN</a> <a href="./../gps_compass/rtk_gps">RTK GPS</a>, <a href="https://www.u-blox.com/en/product/zed-f9p-module" target="_blank" rel="noreferrer">u-blox F9P</a>, magnetometer, barometer, IMU, buzzer, and safety switch module.</p><p><img src="'+a+'" alt="ARK RTK GPS L1 L5"></p><h2 id="де-купити" tabindex="-1">Де купити <a class="header-anchor" href="#де-купити" aria-label="Permalink to &quot;Де купити&quot;">​</a></h2><p>Замовте цей модуль з:</p><ul><li><a href="https://arkelectron.com/product/ark-rtk-gps-l1-l5/" target="_blank" rel="noreferrer">ARK Electronics</a> (US)</li></ul><h2 id="характеристики-обладнання" tabindex="-1">Характеристики обладнання <a class="header-anchor" href="#характеристики-обладнання" aria-label="Permalink to &quot;Характеристики обладнання&quot;">​</a></h2><ul><li><a href="https://github.com/ARK-Electronics/ARK_RTK_GPS" target="_blank" rel="noreferrer">Open Source Schematic and BOM</a></li><li>Датчики <ul><li>Ublox F9P GPS <ul><li>Multi-band GNSS receiver delivers centimetre level accuracy in seconds</li><li>Одночасний прийом GPS, GLONASS, Galileo та BeiDou</li><li>Багатосмуговий RTK зі швидкими часами збіжності та надійною продуктивністю</li><li>Висока швидкість оновлення для високодинамічних додатків</li><li>Centimetre accuracy in a small and energy efficient module</li><li>Does not Support Moving Base for Heading</li></ul></li><li>Bosch BMM150 Magnetometer</li><li>Bosch BMP388 Barometer</li><li>Invensense ICM-42688-P 6-Axis IMU</li></ul></li><li>STM32F412CEU6 MCU</li><li>Кнопка безпеки</li><li>Зумер</li><li>Два роз&#39;єми стандарту CAN для Pixhawk (4 контакти JST GH)</li><li>F9P <code>UART 2</code> Connector <ul><li>3-контактний JST-GH</li><li>TX, RX, GND</li></ul></li><li>Роз&#39;єм для відлагодження стандарту Pixhawk (6 контактів JST SH)</li><li>LED індикатори <ul><li>Індикатор безпеки</li><li>GPS Fix</li><li>Статус RTK</li><li>RGB Статус системи</li></ul></li><li>USA Built</li><li>Вимоги до живлення <ul><li>5V</li><li>Середній струм 170мA</li><li>180мА Макс</li></ul></li></ul><h2 id="налаштування-програмного-забезпечення" tabindex="-1">Налаштування програмного забезпечення <a class="header-anchor" href="#налаштування-програмного-забезпечення" aria-label="Permalink to &quot;Налаштування програмного забезпечення&quot;">​</a></h2><h3 id="підключення" tabindex="-1">Підключення <a class="header-anchor" href="#підключення" aria-label="Permalink to &quot;Підключення&quot;">​</a></h3><p>The ARK RTK GPS L1 L5 is connected to the CAN bus using a Pixhawk standard 4 pin JST GH cable. For more information, refer to the <a href="./../can/#wiring">CAN Wiring</a> instructions.</p><h3 id="встановлення" tabindex="-1">Встановлення <a class="header-anchor" href="#встановлення" aria-label="Permalink to &quot;Встановлення&quot;">​</a></h3><p>The recommended mounting orientation is with the connectors on the board pointing towards the <strong>back of vehicle</strong>.</p><p>The sensor can be mounted anywhere on the frame, but you will need to specify its position, relative to vehicle centre of gravity, during <a href="#px4-configuration">PX4 configuration</a>.</p><h2 id="налаштування-прошивки" tabindex="-1">Налаштування прошивки <a class="header-anchor" href="#налаштування-прошивки" aria-label="Permalink to &quot;Налаштування прошивки&quot;">​</a></h2><p>ARK RTK GPS L1 L5 runs the <a href="./px4_cannode_fw">PX4 cannode firmware</a>. As such, it supports firmware update over the CAN bus and <a href="./#node-id-allocation">dynamic node allocation</a>.</p><p>ARK RTK GPS L1 L5 boards ship with recent firmware pre-installed, but if you want to build and flash the latest firmware yourself, refer to the <a href="./px4_cannode_fw#building-the-firmware">cannode firmware build instructions</a>.</p><p>Firmware target: <code>ark_can-rtk-gps_default</code> Bootloader target: <code>ark_can-rtk-gps_canbootloader</code></p><h2 id="налаштування-польотного-контролера" tabindex="-1">Налаштування польотного контролера <a class="header-anchor" href="#налаштування-польотного-контролера" aria-label="Permalink to &quot;Налаштування польотного контролера&quot;">​</a></h2><h3 id="увімкнення-dronecan" tabindex="-1">Увімкнення DroneCAN <a class="header-anchor" href="#увімкнення-dronecan" aria-label="Permalink to &quot;Увімкнення DroneCAN&quot;">​</a></h3><p>In order to use the ARK RTK GPS L1 L5, connect it to the Pixhawk CAN bus and enable the DroneCAN driver by setting parameter <a href="./../advanced_config/parameter_reference#UAVCAN_ENABLE">UAVCAN_ENABLE</a> to <code>2</code> for dynamic node allocation (or <code>3</code> if using <a href="./../dronecan/escs">DroneCAN ESCs</a>).</p><p>Кроки наступні:</p><ul><li>In <em>QGroundControl</em> set the parameter <a href="./../advanced_config/parameter_reference#UAVCAN_ENABLE">UAVCAN_ENABLE</a> to <code>2</code> or <code>3</code> and reboot (see <a href="./../advanced_config/parameters">Finding/Updating Parameters</a>).</li><li>Connect ARK RTK GPS L1 L5 CAN to the Pixhawk CAN.</li></ul><p>Після активації модуль буде виявлено при завантаженні. Дані GPS повинні надходити з частотою 10 Гц.</p><h3 id="конфігурація-px4" tabindex="-1">Конфігурація PX4 <a class="header-anchor" href="#конфігурація-px4" aria-label="Permalink to &quot;Конфігурація PX4&quot;">​</a></h3><p>You need to set necessary <a href="./">DroneCAN</a> parameters and define offsets if the sensor is not centred within the vehicle:</p><ul><li>Enable GPS yaw fusion by setting bit 3 of <a href="./../advanced_config/parameter_reference#EKF2_GPS_CTRL">EKF2_GPS_CTRL</a> to true.</li><li>Enable GPS blending to ensure the heading is always published by setting <a href="./../advanced_config/parameter_reference#SENS_GPS_MASK">SENS_GPS_MASK</a> to 7 (all three bits checked).</li><li>Enable <a href="./../advanced_config/parameter_reference#UAVCAN_SUB_GPS">UAVCAN_SUB_GPS</a>, <a href="./../advanced_config/parameter_reference#UAVCAN_SUB_MAG">UAVCAN_SUB_MAG</a>, and <a href="./../advanced_config/parameter_reference#UAVCAN_SUB_BARO">UAVCAN_SUB_BARO</a>.</li><li>The parameters <a href="./../advanced_config/parameter_reference#SENS_GPS0_OFFX">SENS_GPS0_OFFX</a>, <a href="./../advanced_config/parameter_reference#SENS_GPS0_OFFY">SENS_GPS0_OFFY</a> and <a href="./../advanced_config/parameter_reference#SENS_GPS0_OFFZ">SENS_GPS0_OFFZ</a> can be set to account for the offset of the ARK RTK GPS L1 L5 from the vehicles centre of gravity.</li></ul><h3 id="ark-rtk-gps-l1-l5-configuration" tabindex="-1">ARK RTK GPS L1 L5 Configuration <a class="header-anchor" href="#ark-rtk-gps-l1-l5-configuration" aria-label="Permalink to &quot;ARK RTK GPS L1 L5 Configuration&quot;">​</a></h3><p>You may need to <a href="./../dronecan/#qgc-cannode-parameter-configuration">configure the following parameters</a> on the ARK RTK GPS L1 L5 itself:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Опис</th></tr></thead><tbody><tr><td><a id="CANNODE_NODE_ID"></a><a href="./../advanced_config/parameter_reference#CANNODE_NODE_ID">CANNODE_NODE_ID</a></td><td>CAN node ID (0 for dynamic allocation). If set to 0 (default), dynamic node allocation is used. Set to 1-125 to use a static node ID.</td></tr><tr><td><a id="CANNODE_TERM"></a><a href="./../advanced_config/parameter_reference#CANNODE_TERM">CANNODE_TERM</a></td><td>Вбудована завершення шини CAN. Set to <code>1</code> if this is the last node on the CAN bus.</td></tr></tbody></table><h3 id="setting-up-rover-and-fixed-base" tabindex="-1">Setting Up Rover and Fixed Base <a class="header-anchor" href="#setting-up-rover-and-fixed-base" aria-label="Permalink to &quot;Setting Up Rover and Fixed Base&quot;">​</a></h3><p>Position of the rover is established using RTCM messages from the RTK base module (the base module is connected to QGC, which sends the RTCM information to PX4 via MAVLink).</p><p>Параметри PX4 DroneCAN:</p><ul><li><a href="./../advanced_config/parameter_reference#UAVCAN_PUB_RTCM">UAVCAN_PUB_RTCM</a>: <ul><li>Makes PX4 publish RTCM messages (<a href="https://dronecan.github.io/Specification/7._List_of_standard_data_types/#rtcmstream" target="_blank" rel="noreferrer">RTCMStream</a>) to the bus (which it gets from the RTK base module via QGC).</li></ul></li></ul><p>Rover module parameters (also <a href="./../dronecan/#qgc-cannode-parameter-configuration">set using QGC</a>):</p><ul><li><a href="./../advanced_config/parameter_reference#CANNODE_SUB_RTCM">CANNODE_SUB_RTCM</a> tells the rover that it should subscribe to <a href="https://dronecan.github.io/Specification/7._List_of_standard_data_types/#rtcmstream" target="_blank" rel="noreferrer">RTCMStream</a> RTCM messages on the bus (from the moving base).</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Use <a href="./../advanced_config/parameter_reference#UAVCAN_PUB_MBD">UAVCAN_PUB_MBD</a> and <a href="./../advanced_config/parameter_reference#CANNODE_SUB_MBD">CANNODE_SUB_MBD</a> instead if you want to implement moving base (see below) at the same time.</p></div><p>For more information see <a href="./../dronecan/#rover-and-fixed-base">Rover and Fixed Base</a> in the DroneCAN guide.</p><h2 id="значення-led-індикаторів" tabindex="-1">Значення LED індикаторів <a class="header-anchor" href="#значення-led-індикаторів" aria-label="Permalink to &quot;Значення LED індикаторів&quot;">​</a></h2><ul><li><p>Світлодіоди статусу GPS розташовані праворуч від роз&#39;ємів</p><ul><li>Миготіння зеленого - це фіксація GPS</li><li>Миготіння синього - це отримані корекції та RTK Float</li><li>Сталий синій - це RTK зафіксовано</li></ul></li><li><p>Світлодіоди статусу CAN розташовані зверху ліворуч від роз&#39;ємів</p><ul><li>Повільне блимання зеленого - чекає на підключення CAN</li><li>Швидко блимаюче зелене світло - нормальна робота</li><li>Повільне блимання зеленим і синім - перелік CAN</li><li>Fast blinking blue and red is firmware update in progress</li><li>Миготливий червоний - помилка <ul><li>Якщо ви бачите червоний світлодіод, це означає, що виникла помилка, і вам слід перевірити наступне <ul><li>Переконайтеся, що у польотному контролері встановлено SD-картку</li><li>Make sure the ARK RTK GPS L1 L5 has <code>ark_can-rtk-gps_canbootloader</code> installed prior to flashing <code>ark_can-rtk-gps_default</code></li><li>Видаліть бінарні файли з кореневих та ufw директорій SD-карти та спробуйте зібрати та знову прошити</li></ul></li></ul></li></ul></li></ul><h3 id="оновлення-модуля-ublox-f9p" tabindex="-1">Оновлення модуля Ublox F9P <a class="header-anchor" href="#оновлення-модуля-ublox-f9p" aria-label="Permalink to &quot;Оновлення модуля Ublox F9P&quot;">​</a></h3><p>ARK RTK GPS L1 L5 comes with the Ublox F9P module up to date with version 1.13 or newer. Проте ви можете перевірити версію та оновити прошивку за бажанням.</p><p>Кроки наступні:</p><ol><li><a href="https://www.u-blox.com/en/product/u-center" target="_blank" rel="noreferrer">Download u-center from u-blox.com</a> and install on your PC (Windows only)</li><li>Open the <a href="https://www.u-blox.com/en/product/zed-f9p-module#tab-documentation-resources" target="_blank" rel="noreferrer">u-blox ZED-F9P website</a></li><li>Прокрутіть вниз і клацніть на поле &quot;Show Legacy Documents&quot;</li><li>Прокрутіть вниз ще раз до Оновлення прошивки та завантажте потрібну прошивку (потрібна версія не нижче 1.13)</li><li>While holding down the safety switch on the ARK RTK GPS L1 L5, connect it to power via one of its CAN ports and hold until all 3 LEDs blink rapidly</li><li>Connect the ARK RTK GPS L1 L5 to your PC via its debug port with a cable such as the Black Magic Probe or an FTDI</li><li>Open u-center, select the COM port for the ARK RTK GPS L1 L5 and connect <img src="'+r+'" alt="U-Center Connect"></li><li>Check the current firmware version by selecting View, Messages View, UBX, MON, VER <img src="'+t+'" alt="Check Version"></li><li>Для оновлення прошивки: <ol><li>Виберіть Tools, Firmware Update</li><li>Поле зображення прошивки повинно бути файлом .bin, завантаженим зі сторінки веб-сайту u-blox ZED-F9P</li><li>Поставте прапорець &quot;Використовувати цю швидкість передачі для оновлення&quot; та виберіть 115200 зі списку</li><li>Переконайтеся, що інші прапорці відображаються так, як показано нижче</li><li>Натисніть зелену кнопку GO внизу зліва</li><li>&quot;Firmware Update SUCCESS&quot; should be displayed if it updated successfully <img src="'+i+'" alt="Firmware Update"></li></ol></li></ol><h2 id="дивіться-також" tabindex="-1">Дивіться також <a class="header-anchor" href="#дивіться-також" aria-label="Permalink to &quot;Дивіться також&quot;">​</a></h2><ul><li><a href="https://arkelectron.gitbook.io/ark-documentation/sensors/ark-rtk-gps" target="_blank" rel="noreferrer">ARK RTK GPS L1 L5 Documentation</a> (ARK Docs)</li></ul>',46)])])}const A=o(d,[["render",c]]);export{S as __pageData,A as default};
